contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    receive() external payable {}

    function run(uint256 depositAmount1, uint256 depositAmount2) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depositAmount1) + (depositAmount2)); require(depositAmount1 <= 1000000000000000000000000000000); require(depositAmount2 <= 1000000000000000000000000000000);
        require(address(this).balance >= depositAmount1 + depositAmount2);

        uint256 contractBalanceBefore = address(c).balance;

        c.deposit{value: depositAmount1}(); if (__ESBMC_reverted()) return;
        uint256 contractBalanceAfterDeposit1 = address(c).balance;

        c.deposit{value: depositAmount2}(); if (__ESBMC_reverted()) return;
        uint256 contractBalanceAfterDeposit2 = address(c).balance;

        bool reverted;
        c.withdrawAll(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint256 contractBalanceAfterWithdraw = address(c).balance;

        assert(
            contractBalanceAfterDeposit1 == contractBalanceBefore + depositAmount1 &&
            contractBalanceAfterDeposit2 == contractBalanceAfterDeposit1 + depositAmount2 &&
            (reverted || contractBalanceAfterWithdraw == contractBalanceAfterDeposit2 - (depositAmount1 + depositAmount2))
        );
    }
}

