// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ReentrancyDAO c;

    function setUp() public {
        c = new ReentrancyDAO();
    }

    function _run(uint256 depositAmount1, uint256 depositAmount2) internal {
        depositAmount1 = bound(depositAmount1, 0, 1000000000000000000000000000000);
        depositAmount2 = bound(depositAmount2, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP + VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= depositAmount1 + depositAmount2);
        uint256 contractBalanceBefore = address(c).balance;
        try c.deposit{value: depositAmount1}() {} catch { return; }
        uint256 contractBalanceAfterDeposit1 = address(c).balance;
        try c.deposit{value: depositAmount2}() {} catch { return; }
        uint256 contractBalanceAfterDeposit2 = address(c).balance;
        bool reverted;
        try c.withdrawAll() {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 contractBalanceAfterWithdraw = address(c).balance;
        assertTrue(contractBalanceAfterDeposit1 == contractBalanceBefore + depositAmount1 &&
            contractBalanceAfterDeposit2 == contractBalanceAfterDeposit1 + depositAmount2 &&
            (reverted || contractBalanceAfterWithdraw == contractBalanceAfterDeposit2 - (depositAmount1 + depositAmount2)));
    }

    function testFuzz_run(uint256 depositAmount1, uint256 depositAmount2) public {
        _run(depositAmount1, depositAmount2);
    }

    receive() external payable {}
}
